/**
 * Post Story Test Automation Review Comments Action
 * Handles the bulk review result for a Story PR.
 * - APPROVED → add pr_approved label, trigger story_test_automation_merge
 * - REQUEST_CHANGES / BLOCK → move Story to In Rework, trigger story_test_automation_rework
 *
 * Posts comments through the SCM abstraction (same as pr_review) so that
 * inline comments become diff conversation threads rather than generic PR comments.
 *
 * gh-1008 CRAP split: diff/comment helpers live in
 * js/postStoryTestAutomationReviewHelpers.js; tracker/label helpers in
 * js/postStoryTestAutomationShared.js; action() is a thin orchestrator.
 */

const { LABELS } = require('./config.js');
const scmModule = require('./common/scm.js');
const ghHelpers = require('./common/githubHelpers.js');
const autoStart = require('./common/autoStart.js');
const configLoader = require('./configLoader.js');
const outputFiles = require('./common/outputFiles.js');
const tokenUsageComment = require('./common/tokenUsageComment.js');
const prReviewComments = require('./postPRReviewComments.js');
const shared = require('./postStoryTestAutomationShared.js');
const reviewHelpers = require('./postStoryTestAutomationReviewHelpers.js');

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var trackerHolder = shared.createTrackerHolder(trackersModule);
function initTracker(config, customParams) {
    trackerHolder.initTracker(config, customParams);
}
function getTracker() {
    return trackerHolder.getTracker();
}

function readFile(path) {
    return outputFiles.readOutputFile(path, {});
}

function readReviewJson(storyKey, workingDir) {
    try {
        const raw = outputFiles.readOutputFile('pr_review.json', {
            ticketKey: storyKey,
            workingDir: workingDir
        });
        if (!raw) return null;
        return JSON.parse(raw);
    } catch (e) {
        console.error('Failed to parse pr_review.json:', e);
        return null;
    }
}

function resolveCustomParams(params, config) {
    var merged = {};
    var patch = configLoader.resolveInstructions('pr_story_test_automation_review', null, config).jobParamPatch;
    if (patch && patch.customParams) {
        Object.assign(merged, patch.customParams);
    }
    Object.assign(merged,
        (params.jobParams && params.jobParams.customParams) || params.customParams || {}
    );
    return merged;
}

function getRepoInfo(config) {
    if (config && config.repository && config.repository.owner && config.repository.repo) {
        return { owner: config.repository.owner, repo: config.repository.repo };
    }
    try {
        return ghHelpers.getGitHubRepoInfo();
    } catch (e) {
        console.warn('Could not determine repo info:', e.message || e);
        return null;
    }
}

function triggerMerge(storyKey, config, customParams) {
    if (!customParams || !customParams.autoStartMerge || !customParams.autoStartMergeConfigFile) {
        return false;
    }
    try {
        return autoStart.triggerConfiguredWorkflowForTicket({
            ticketKey: storyKey,
            customParams: customParams,
            config: config,
            configFile: customParams.autoStartMergeConfigFile,
            label: 'story_test_automation_merge',
            stripKeys: ['removeLabel', 'autoStartMerge', 'autoStartMergeConfigFile']
        });
    } catch (e) {
        console.warn('⚠️ autoStartMerge trigger failed:', e.message || e);
        return false;
    }
}

function triggerRework(storyKey, config, customParams) {
    if (!customParams || !customParams.autoStartRework || !customParams.autoStartReworkConfigFile) {
        return false;
    }
    try {
        return autoStart.triggerConfiguredWorkflowForTicket({
            ticketKey: storyKey,
            customParams: customParams,
            config: config,
            configFile: customParams.autoStartReworkConfigFile,
            label: 'story_test_automation_rework',
            stripKeys: ['removeLabel', 'autoStartRework', 'autoStartReworkConfigFile']
        });
    } catch (e) {
        console.warn('⚠️ autoStartRework trigger failed:', e.message || e);
        return false;
    }
}

function removeAutomationLabels(storyKey, params, customParams) {
    const wipLabel = params.metadata && params.metadata.contextId
        ? params.metadata.contextId + '_wip'
        : 'pr_story_test_automation_review_wip';
    shared.removeLabelSafely(getTracker, storyKey, wipLabel);

    const smTriggerLabel = customParams && customParams.removeLabel;
    if (smTriggerLabel) {
        if (shared.removeLabelSafely(getTracker, storyKey, smTriggerLabel)) {
            console.log('✅ Removed SM trigger label:', smTriggerLabel);
        }
    }
}

/**
 * Posts the numbered rework feedback (inline comments + general comment) to
 * the tracker so the rework agent sees what must be addressed.
 */
function postReworkFeedback(storyKey, reviewData, inlineComments) {
    if (!inlineComments || inlineComments.length === 0) return;

    try {
        var feedback = reviewHelpers.buildReworkFeedback({
            generalComment: reviewData.generalComment,
            inlineComments: inlineComments
        }, readFile);
        getTracker().postComment(storyKey, feedback);
        console.log('✅ Posted detailed rework feedback to Jira');
    } catch (e) {
        console.warn('Failed to post detailed rework feedback:', e);
    }
}

function action(params) {
    try {
        const storyKey = params.ticket.key;
        const config = configLoader.loadProjectConfig(params.jobParams || params);
        const customParams = resolveCustomParams(params, config);
        initTracker(config, customParams);
        const workingDir = config.workingDir || null;
        const scm = scmModule.createScm(config);

        console.log('=== Processing story test automation review for', storyKey, '===');

        const reviewData = readReviewJson(storyKey, workingDir);
        if (!reviewData) {
            getTracker().postComment(storyKey, 'h3. ⚠️ Story Test Review Error\n\nCould not read pr_review.json. Removed SM trigger label so SM can retry.');
            removeAutomationLabels(storyKey, params, customParams);
            return { success: false, error: 'No review data found' };
        }

        const isApproved = (reviewData.recommendation || '').replace(/^APPROVED$/, 'APPROVE') === 'APPROVE';
        console.log('Review recommendation:', reviewData.recommendation);

        const { prNumber, prUrl } = reviewHelpers.getPRNumber(params, storyKey, scm, readFile);
        const repoInfo = getRepoInfo(config);

        var inlineComments = reviewHelpers.filterInlineCommentsByDiff(scm, prNumber, reviewData.inlineComments, prReviewComments);

        if (prNumber) {
            reviewHelpers.resolveExistingAgentReviewThreads(scm, prNumber, repoInfo, ghHelpers.fetchDiscussionsAndRawData);

            if (inlineComments && inlineComments.length > 0) {
                console.log('Posting ' + inlineComments.length + ' inline comment(s)');
                inlineComments.forEach(function(ic, index) {
                    console.log('Processing inline comment ' + (index + 1) + '/' + inlineComments.length);
                    reviewHelpers.postInlineComment(scm, prNumber, ic, storyKey, readFile, prReviewComments);
                });
            }

            // Post the general comment AFTER inline comments.
            if (reviewData.generalComment) {
                reviewHelpers.postGeneralComment(scm, prNumber, reviewData.generalComment, storyKey, workingDir, outputFiles);
            }
            prReviewComments.resolveApprovedThreads(scm, prNumber, reviewData.resolvedThreadIds);

            reviewHelpers.applyVerdictLabels(scm, prNumber, storyKey, isApproved, getTracker, LABELS);
        } else {
            console.warn('No PR number found — skipping GitHub comments');
        }

        if (params.response) {
            try {
                getTracker().postComment(storyKey, params.response);
            } catch (e) {
                console.warn('Failed to post Jira review comment:', e);
            }
        }

        if (!isApproved) {
            postReworkFeedback(storyKey, reviewData, inlineComments);
        }

        if (isApproved) {
            console.log('✅ Story PR approved — triggering merge agent');
            if (!triggerMerge(storyKey, config, customParams)) {
                autoStart.triggerSmIfIdle({ config: config, customParams: customParams });
            }
        } else {
            console.log('📝 Changes requested on test-automation PR — keeping ticket in In Testing for rework');
            if (!triggerRework(storyKey, config, customParams)) {
                autoStart.triggerSmIfIdle({ config: config, customParams: customParams });
            }
        }

        try {
            getTracker().addLabel(storyKey, LABELS.AI_PR_REVIEWED);
        } catch (e) {}

        removeAutomationLabels(storyKey, params, customParams);

        try {
            tokenUsageComment.postTokenUsageComments(storyKey, { initiator: params.initiator, customParams: tokenUsageComment.customParamsOf(params) });
        } catch (e) {
            console.warn('Failed to post token usage comments:', e);
        }

        return {
            success: true,
            recommendation: reviewData.recommendation,
            storyKey: storyKey,
            prUrl: prUrl
        };

    } catch (error) {
        console.error('❌ Error in postStoryTestAutomationReview:', error);
        try {
            const storyKey = params.ticket ? params.ticket.key : null;
            if (storyKey) {
                getTracker().removeLabel(storyKey, 'sm_story_test_review_triggered');
                getTracker().postComment(storyKey, 'h3. ❌ Story Test Review Error\n\n{code}' + error.toString() + '{code}');
            }
        } catch (e) {}
        return { success: false, error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

/**
 * Pre-CLI Story Test Automation Setup Action
 * 1. Fetches all linked Test Cases for the Story.
 * 2. Writes input/{STORY_KEY}/linked_test_cases.json and .md.
 * 3. Checks out test/{STORY_KEY} branch and keeps it synced with origin/main:
 *    - if the branch was already merged → delete it and recreate from fresh main;
 *    - if it has unmerged test work → merge origin/main into it;
 *    - on merge conflicts → write merge_conflicts.md + pr_diff.txt so the agent can resolve them.
 */

var configLoader = require('./configLoader.js');
var prHelper = require('./common/pullRequest.js');
var scmModule = require('./common/scm.js');
var gh = require('./common/githubHelpers.js');
const { STATUSES, resolveStatuses } = require('./config.js');
var trackersModule = require('./common/trackers.js');

// Canonical copy (gh-823/gh-912): the warning:/note: line filter lives in
// common/pullRequest.js once — this delegate keeps every local call site.
function cleanCommandOutput(output) {
    return prHelper.cleanCommandOutput(output);
}

var MAX_DISCUSSION_THREADS = 100;

function trimDiscussionsMarkdown(markdown, maxThreads) {
    if (!markdown || maxThreads <= 0) return markdown;
    var marker = '\n### Thread ';
    var idx = markdown.indexOf(marker);
    if (idx === -1) return markdown;
    var header = markdown.substring(0, idx);
    var rest = markdown.substring(idx + marker.length);
    var sections = rest.split(marker);
    if (sections.length <= maxThreads) return markdown;
    var kept = sections.slice(sections.length - maxThreads);
    return header + marker + kept.join(marker);
}

function runGit(command, workingDir) {
    var args = { command: command };
    if (workingDir) args.workingDirectory = workingDir;
    return cli_execute_command(args);
}

function writeBranchConflictGuidance(storyKey, branchName, baseBranch, details) {
    try {
        file_write({
            path: 'input/' + storyKey + '/merge_conflicts.md',
            content: '# Branch Conflict Guidance\n\n' +
                'Branch `' + branchName + '` has test automation work that is not already merged into `origin/' + baseBranch + '`, ' +
                'and `origin/' + baseBranch + '` is not an ancestor of this branch.\n\n' +
                'Before editing tests, sync the branch deliberately with `origin/' + baseBranch + '`. ' +
                'In most cases, prefer `origin/' + baseBranch + '` for repository setup, generated workflow/config files, ' +
                'and shared infrastructure, then re-apply only the ticket-specific test automation that is still relevant.\n\n' +
                'Do not discard test files that are still needed for this ticket. Do not keep stale bootstrap/setup files just because they exist on the old branch.\n\n' +
                'Details:\n\n```\n' + (details || '(not available)') + '\n```\n'
        });
    } catch (e) {
        console.warn('Could not write branch conflict guidance:', e);
    }
}

function isAncestorRef(ancestor, descendant, workingDir) {
    try {
        var output = cleanCommandOutput(
            runGit('git rev-list -1 ' + ancestor + ' --not ' + descendant, workingDir) || ''
        );
        return output.trim() === '';
    } catch (e) {
        console.warn('Could not inspect branch ancestry for ' + ancestor + ' -> ' + descendant + ':', e);
        return false;
    }
}

function alignBranchWithBase(storyKey, branchName, baseBranch, workingDir, inputFolder) {
    // Make sure remote refs are fresh before any merge/ancestor decision —
    // targeted: just this branch and its base (owner rule 2026-10-03).
    try {
        var targetedFetch = prHelper.buildTargetedOriginFetchCommand([branchName, baseBranch]);
        if (targetedFetch) runGit(targetedFetch, workingDir);
    } catch (e) {
        console.warn('Could not fetch remote branches during align:', e);
    }

    var localExists = cleanCommandOutput(
        runGit('git branch --list "' + branchName + '"', workingDir) || ''
    ).trim() !== '';
    var remoteExists = false;
    try {
        // gh-912: decide on a real refs/heads/<branch> ref line — a
        // warning-only capture (central-mode insteadOf origin, git ≥ 2.54)
        // must classify as "branch absent".
        remoteExists = prHelper.remoteBranchExists(runGit, workingDir, branchName);
    } catch (e) {
        console.warn('Error checking remote branches:', e);
    }

    if (!localExists && !remoteExists) {
        console.log('Creating new test branch from', baseBranch + ':', branchName);
        runGit('git checkout ' + baseBranch, workingDir);
        runGit('git pull origin ' + baseBranch, workingDir);
        runGit('git checkout -b ' + branchName, workingDir);
        return;
    }

    if (!localExists && remoteExists) {
        console.log('Checking out remote test branch:', branchName);
        runGit('git checkout -b ' + branchName + ' origin/' + branchName, workingDir);
    } else {
        console.log('Switching to existing local test branch:', branchName);
        runGit('git checkout ' + branchName, workingDir);
    }

    // Case 1: the test branch has already been merged into main.
    // Drop the stale branch (local + remote) and create a fresh one from main.
    if (isAncestorRef('HEAD', 'origin/' + baseBranch, workingDir)) {
        console.log('Test branch ' + branchName + ' is already merged into origin/' + baseBranch + '; recreating from fresh ' + baseBranch);
        runGit('git checkout ' + baseBranch, workingDir);
        try {
            runGit('git branch -D ' + branchName, workingDir);
        } catch (e) {
            console.warn('Could not delete local test branch:', e);
        }
        try {
            runGit('git push origin --delete ' + branchName, workingDir);
        } catch (e) {
            console.warn('Could not delete remote test branch:', e);
        }
        runGit('git pull origin ' + baseBranch, workingDir);
        runGit('git checkout -b ' + branchName, workingDir);
        return;
    }

    // Case 2: branch has unmerged test work — always pull main into it.
    console.log('Merging origin/' + baseBranch + ' into test branch ' + branchName);
    var conflictFiles = gh.detectMergeConflicts(baseBranch, inputFolder, workingDir);
    if (conflictFiles.length > 0) {
        console.warn('⚠️ Merge conflicts detected after pulling origin/' + baseBranch + ':', conflictFiles.join(', '));
        try {
            var diff = gh.getPRDiff(baseBranch, branchName, workingDir);
            if (diff) {
                file_write({
                    path: inputFolder + '/pr_diff.txt',
                    content: gh.trimLargeTextForInput(diff, 'PR Diff', 12000)
                });
                console.log('✅ Wrote pr_diff.txt for conflict resolution');
            }
        } catch (e) {
            console.warn('Could not write pr_diff.txt:', e);
        }
        writeBranchConflictGuidance(
            storyKey,
            branchName,
            baseBranch,
            'Merge conflicts after pulling origin/' + baseBranch + ' into ' + branchName + ':\n\n' +
            conflictFiles.map(function(f) { return '* ' + f; }).join('\n') + '\n\n' +
            'Resolve conflicts, stage the files, and continue. The post-action will commit and push the resolved test code.'
        );
    } else {
        console.log('✅ Merged origin/' + baseBranch + ' cleanly into test branch ' + branchName);
    }
}

function checkoutBranch(storyKey, config, inputFolder) {
    var branchName = configLoader.formatBranchName(config.git.branchPrefix.test, storyKey);
    var workingDir = config.workingDir || null;
    console.log('Setting up branch:', branchName);

    try {
        runGit('git config user.name "' + config.git.authorName + '"', workingDir);
        runGit('git config user.email "' + config.git.authorEmail + '"', workingDir);
    } catch (e) {
        console.warn('Failed to configure git author:', e);
    }

    try {
        var setupFetch = prHelper.buildTargetedOriginFetchCommand([branchName, config.git.baseBranch]);
        if (setupFetch) runGit(setupFetch, workingDir);
    } catch (e) {
        console.warn('Could not fetch remote branches:', e);
    }

    alignBranchWithBase(storyKey, branchName, config.git.baseBranch, workingDir, inputFolder);

    console.log('✅ Branch ready:', branchName);
}

function fetchLinkedTestCases(storyKey, testCaseType, tracker) {
    var jql = 'issue in linkedIssues("' + storyKey + '") AND issuetype = "' + testCaseType + '"';
    console.log('Fetching linked Test Cases with JQL:', jql);
    try {
        // JQL text: provider-specific query (WIQL on ado)
        var results = tracker.searchIssues(jql, { maxResults: 100, fields: ['key', 'summary', 'status'] });
        return Array.isArray(results) ? results : [];
    } catch (e) {
        console.warn('Failed to fetch linked Test Cases:', e);
        return [];
    }
}

function renderTestCase(tc) {
    var fields = tc.fields || {};
    var lines = [];
    lines.push('- ' + tc.key + ' — ' + (fields.summary || '(no summary)') +
               ' [' + (fields.status && fields.status.name ? fields.status.name : 'Unknown') + ']');
    return lines.join('\n');
}

function writeLinkedTestCases(storyKey, testCases) {
    var inputDir = 'input/' + storyKey;
    try {
        file_write({
            path: inputDir + '/linked_test_cases.json',
            content: JSON.stringify({ storyKey: storyKey, testCases: testCases }, null, 2)
        });
    } catch (e) {
        console.warn('Could not write linked_test_cases.json:', e);
    }

    var md = '# Linked Test Cases for ' + storyKey + '\n\n';
    md += 'Total: ' + testCases.length + '\n\n';
    testCases.forEach(function(tc) {
        md += renderTestCase(tc) + '\n';
    });
    md += '\n';

    try {
        file_write({
            path: inputDir + '/linked_test_cases.md',
            content: md
        });
    } catch (e) {
        console.warn('Could not write linked_test_cases.md:', e);
    }
}

function findTestPr(scm, storyKey, config) {
    try {
        var branchName = configLoader.formatBranchName(config.git.branchPrefix.test, storyKey);
        var openPRs = scm.listPrs('open') || [];
        return openPRs.find(function(pr) {
            return pr.head && pr.head.ref && pr.head.ref === branchName;
        }) || null;
    } catch (e) {
        console.warn('Could not list open PRs for test branch:', e);
        return null;
    }
}

// ── gh-930: writePrContext split into formatting helpers ────────────────────
// Every helper is source-agnostic: it only consumes the scm abstraction
// (getPrDiff / fetchDiscussions) and the PR object shape, so GitHub, GitLab
// and ADO PRs flow through the same code paths.

function prUserLogin(pr) {
    return pr.user && pr.user.login ? pr.user.login : '';
}

function prBranchPair(pr) {
    return '`' + (pr.head && pr.head.ref ? pr.head.ref : '') + '` → `' + (pr.base && pr.base.ref ? pr.base.ref : '') + '`';
}

function buildPrInfoMarkdown(pr) {
    return '# Pull Request Information\n' +
        '- **PR #**: ' + (pr.number || '') + '\n' +
        '- **URL**: ' + (pr.html_url || '') + '\n' +
        '- **Title**: ' + (pr.title || '') + '\n' +
        '- **Author**: ' + prUserLogin(pr) + '\n' +
        '- **Branch**: ' + prBranchPair(pr) + '\n' +
        '- **State**: ' + (pr.state || '') + '\n';
}

function writePrInfo(inputDir, pr) {
    try {
        file_write({ path: inputDir + '/pr_info.md', content: buildPrInfoMarkdown(pr) });
        console.log('✅ Wrote pr_info.md for PR #' + pr.number);
    } catch (e) {
        console.warn('Could not write pr_info.md:', e);
    }
}

function writePrDiff(inputDir, scm, pr) {
    try {
        var diff = scm.getPrDiff(pr.number);
        if (diff) {
            file_write({ path: inputDir + '/pr_diff.txt', content: diff });
            console.log('✅ Wrote pr_diff.txt (' + diff.length + ' chars)');
        }
    } catch (e) {
        console.warn('Could not write pr_diff.txt:', e);
    }
}

function writePrDiscussionsMarkdown(inputDir, discussions) {
    if (!discussions || !discussions.markdown) return;
    var trimmedMarkdown = trimDiscussionsMarkdown(discussions.markdown, MAX_DISCUSSION_THREADS);
    if (trimmedMarkdown !== discussions.markdown) {
        console.warn('⚠️ PR discussions markdown truncated from full history to last ' + MAX_DISCUSSION_THREADS + ' threads to keep agent context bounded');
    }
    file_write({ path: inputDir + '/pr_discussions.md', content: trimmedMarkdown });
    console.log('✅ Wrote pr_discussions.md');
}

function openThreadReplies(rawThreads) {
    var threads = rawThreads.threads;
    if (threads.length > MAX_DISCUSSION_THREADS) {
        console.warn('⚠️ PR discussions raw threads truncated from ' + threads.length + ' to last ' + MAX_DISCUSSION_THREADS + ' for review replies');
        threads = threads.slice(threads.length - MAX_DISCUSSION_THREADS);
    }
    return threads
        .filter(function(t) { return !t.resolved && t.body; })
        .map(function(t) {
            return {
                file: t.path,
                line: t.line,
                comment: t.body,
                severity: 'important',
                threadId: t.threadId || t.id || null,
                inReplyToId: t.rootCommentId || t.id || null
            };
        });
}

function writeReviewReplies(replies) {
    if (replies.length > 0) {
        file_write({ path: 'outputs/review_replies.json', content: JSON.stringify({ replies: replies }, null, 2) });
        console.log('✅ Wrote outputs/review_replies.json with', replies.length, 'open review thread(s)');
    }
}

function writePrDiscussions(inputDir, discussions) {
    writePrDiscussionsMarkdown(inputDir, discussions);
    if (discussions && discussions.rawThreads && discussions.rawThreads.threads) {
        writeReviewReplies(openThreadReplies(discussions.rawThreads));
    }
}

function writePrContext(storyKey, scm, pr) {
    var inputDir = 'input/' + storyKey;
    writePrInfo(inputDir, pr);
    writePrDiff(inputDir, scm, pr);
    try {
        writePrDiscussions(inputDir, scm.fetchDiscussions(pr.number));
    } catch (e) {
        console.warn('Could not write PR discussions:', e);
    }
}

function getTestCaseDirectory(tcKey, testFilesPath) {
    var basePath = (testFilesPath || 'testing/').replace(/\/$/, '');
    return basePath + '/tests/' + tcKey;
}

function removeIrrelevantTestCode(testCases, workingDir, testFilesPath, irrelevantStatus) {
    var removed = [];
    testCases.forEach(function(tc) {
        var status = tc.fields && tc.fields.status && tc.fields.status.name;
        if (status !== irrelevantStatus) return;
        var dir = getTestCaseDirectory(tc.key, testFilesPath);
        try {
            var lsOutput = cleanCommandOutput(runGit('git ls-files -- ' + dir, workingDir) || '');
            if (!lsOutput.trim()) {
                console.log('No tracked test code to remove for irrelevant TC:', tc.key);
                return;
            }
            console.log('Removing test code for irrelevant TC:', tc.key, '—', dir);
            runGit('git rm -r --ignore-unmatch -- ' + dir, workingDir);
            removed.push(tc.key);
        } catch (e) {
            console.warn('Failed to remove test code for irrelevant TC', tc.key, ':', e);
        }
    });
    return removed;
}

function action(params) {
    try {
        var actualParams = params.inputFolderPath ? params : (params.jobParams || params);
        var folder = actualParams.inputFolderPath;
        var storyKey = folder.split('/').pop();
        var config = configLoader.loadProjectConfig(params.jobParams || params);
        var projectConfig = configLoader.loadProjectConfig(params.jobParams || params);
        var testCaseType = projectConfig.jira && projectConfig.jira.issueTypes && projectConfig.jira.issueTypes.TEST_CASE
            ? projectConfig.jira.issueTypes.TEST_CASE
            : 'Test Case';
        var customParams = (params.jobParams || params).customParams || {};
        var tracker = trackersModule.createTracker(projectConfig, customParams);
        var statuses = resolveStatuses(customParams);
        var testFilesPath = customParams.testFilesGlob || 'testing/';

        console.log('=== Story test automation setup for:', storyKey, '===');

        // Step 1: Fetch linked test cases
        var testCases = fetchLinkedTestCases(storyKey, testCaseType, tracker);
        console.log('Found', testCases.length, 'linked Test Case(s)');

        if (testCases.length === 0) {
            console.warn('No linked Test Cases found for Story', storyKey);
        }

        writeLinkedTestCases(storyKey, testCases);

        // Step 2: Checkout test/{STORY_KEY} branch, always synced with origin/main
        try {
            checkoutBranch(storyKey, config, folder);
        } catch (e) {
            console.error('Branch checkout failed (non-fatal):', e);
        }

        // Step 3: Fetch PR context for rework when an open test PR exists
        try {
            var scm = scmModule.createScm(projectConfig);
            var pr = findTestPr(scm, storyKey, config);
            if (pr && pr.number) {
                console.log('Open test PR found:', pr.number, '— fetching diff and discussions');
                writePrContext(storyKey, scm, pr);
            } else {
                console.log('No open test PR found for', storyKey);
            }
        } catch (e) {
            console.warn('Fetching PR context failed (non-fatal):', e);
        }

        // Step 4: Remove test code for linked TCs that are marked Irrelevant
        try {
            var removed = removeIrrelevantTestCode(testCases, config.workingDir || null, testFilesPath, statuses.IRRELEVANT || 'Irrelevant');
            if (removed.length > 0) {
                console.log('Removed test code for irrelevant TCs:', removed.join(', '));
            }
        } catch (e) {
            console.warn('Removing irrelevant test code failed (non-fatal):', e);
        }

        console.log('✅ Story test automation setup complete for', storyKey);

    } catch (error) {
        console.error('❌ Error in preCliStoryTestAutomationSetup:', error);
        return { success: false, error: error.toString() };
    }

    return { success: true };
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

/**
 * Post Test Automation Review Comments Action (postJSAction for pr_test_automation_review)
 * Reads outputs/pr_review.json (same format as pr_review agent).
 *
 * If APPROVED:
 *   - Merges PR
 *   - Moves to Passed (if currently In Review - Passed) or Failed (if currently In Review - Failed)
 *
 * If REQUEST_CHANGES / BLOCK:
 *   - Does NOT merge
 *   - Moves to In Rework
 */

const { LABELS } = require('./config.js');
const gh = require('./common/githubHelpers.js');
const autoStart = require('./common/autoStart.js');
const configLoader = require('./configLoader.js');
const outputFiles = require('./common/outputFiles.js');
const trackersModule = require('./common/trackers.js');
const tokenUsageComment = require('./common/tokenUsageComment.js');

function readFile(path) {
    return outputFiles.readOutputFile(path, {});
}

function readReviewJson(ticketKey, workingDir) {
    try {
        const raw = outputFiles.readOutputFile('pr_review.json', {
            ticketKey: ticketKey,
            workingDir: workingDir
        });
        if (!raw) return null;
        return JSON.parse(raw);
    } catch (e) {
        console.error('Failed to parse pr_review.json:', e);
        return null;
    }
}

function getCurrentTicketStatus(ticketKey, tracker) {
    try {
        const ticket = tracker.getIssue(ticketKey);
        return ticket && ticket.fields && ticket.fields.status
            ? ticket.fields.status.name
            : null;
    } catch (e) {
        console.warn('Could not get current ticket status:', e);
        return null;
    }
}

function getPRNumber(params, ticketKey, repoInfo) {
    let prNumber = null;
    let prUrl = null;

    try {
        const inputFolder = params.inputFolderPath || ('input/' + ticketKey);
        const prInfo = readFile(inputFolder + '/pr_info.md');
        if (prInfo) {
            const numMatch = prInfo.match(/\*\*PR #\*\*:\s*(\d+)/);
            const urlMatch = prInfo.match(/\*\*URL\*\*:\s*(https:\/\/[^\s]+)/);
            if (numMatch) prNumber = parseInt(numMatch[1], 10);
            if (urlMatch) prUrl = urlMatch[1];
        }
    } catch (e) {}

    if (!prNumber && repoInfo) {
        // Use exact test/ branch match on open PRs only — never fuzzy-match (would find ai/ feature PRs)
        const branchName = 'test/' + ticketKey;
        try {
            const openPRs = github_list_prs({ workspace: repoInfo.owner, repository: repoInfo.repo, state: 'open' });
            const openMatch = openPRs.filter(function(pr) {
                return pr.head && pr.head.ref && pr.head.ref === branchName;
            });
            if (openMatch.length > 0) {
                prNumber = openMatch[0].number;
                prUrl = openMatch[0].html_url;
            } else {
                console.warn('No open PR found for branch', branchName);
            }
        } catch (e) {
            console.warn('Failed to find test PR by branch:', e);
        }
    }

    return { prNumber: prNumber, prUrl: prUrl };
}

function resolveApprovedThreads(repoInfo, prNumber, resolvedThreadIds) {
    if (!resolvedThreadIds || resolvedThreadIds.length === 0) return;
    console.log('Resolving ' + resolvedThreadIds.length + ' fixed review thread(s)...');
    resolvedThreadIds.forEach(function(threadId) {
        try {
            github_resolve_pr_thread({
                workspace: repoInfo.owner,
                repository: repoInfo.repo,
                pullRequestId: String(prNumber),
                threadId: threadId
            });
            console.log('✅ Resolved thread', threadId);
        } catch (e) {
            console.warn('Failed to resolve thread ' + threadId + ':', e.message || e);
        }
    });
}

function getPrDiff(repoInfo, prNumber) {
    try {
        return github_get_pr_diff({
            workspace: repoInfo.owner,
            repository: repoInfo.repo,
            // pullRequestID — the diff-tool schema casing (both github diff
            // tools declare pullRequestID, unlike the other github_* PR
            // tools that take pullRequestId). Wrong casing makes this call
            // fail every time and the catch below silently skips inline
            // comment validation.
            pullRequestID: String(prNumber)
        }) || '';
    } catch (e) {
        console.warn('Could not fetch PR diff for inline comment validation:', e.message || e);
        return null;
    }
}

function isLinePresentInDiff(diffText, filePath, targetLine) {
    if (!diffText || !filePath || !targetLine) return true;

    var lineNumber = parseInt(targetLine, 10);
    if (!lineNumber) return true;

    var currentFile = null;
    var newLine = null;
    var lines = String(diffText).split(/\r?\n/);

    for (var i = 0; i < lines.length; i++) {
        var line = lines[i];

        if (line.indexOf('diff --git ') === 0) {
            currentFile = null;
            newLine = null;
            continue;
        }

        if (line.indexOf('+++ b/') === 0) {
            currentFile = line.substring('+++ b/'.length);
            continue;
        }

        if (currentFile !== filePath) continue;

        var hunk = line.match(/^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/);
        if (hunk) {
            newLine = parseInt(hunk[1], 10);
            continue;
        }

        if (newLine === null) continue;

        if (line.indexOf('+') === 0 || line.indexOf(' ') === 0) {
            if (newLine === lineNumber) return true;
            newLine++;
        } else if (line.indexOf('-') === 0) {
            continue;
        } else if (line === '\\ No newline at end of file') {
            continue;
        } else {
            newLine++;
        }
    }

    return false;
}

function postFallbackInlineComment(repoInfo, prNumber, filePath, line, commentText) {
    var lineRef = filePath + (line ? ':' + line : '');
    github_add_pr_comment({
        workspace: repoInfo.owner,
        repository: repoInfo.repo,
        pullRequestId: String(prNumber),
        text: '📍 **`' + lineRef + '`**\n\n' + commentText
    });
    console.log('✅ Posted fallback PR comment for ' + lineRef);
}

function postInlineComment(repoInfo, prNumber, inlineComment) {
    const filePath = inlineComment.path || inlineComment.file;
    const commentText = inlineComment.body || readFile(inlineComment.comment);

    try {
        if (!commentText) {
            console.warn('No comment content found for inline comment on', filePath);
            return false;
        }
        if (!filePath) {
            console.warn('No file path found for inline comment');
            return false;
        }

        const params = {
            workspace: repoInfo.owner,
            repository: repoInfo.repo,
            pullRequestId: String(prNumber),
            path: filePath,
            line: String(inlineComment.line),
            text: commentText
        };
        if (inlineComment.startLine) params.startLine = String(inlineComment.startLine);
        if (inlineComment.side) params.side = inlineComment.side;

        var diffText = getPrDiff(repoInfo, prNumber);
        if (diffText !== null && !isLinePresentInDiff(diffText, filePath, inlineComment.line)) {
            console.warn('Inline comment line is not present in PR diff; falling back to PR comment on ' + filePath + ':' + inlineComment.line);
            postFallbackInlineComment(repoInfo, prNumber, filePath, inlineComment.line, commentText);
            return true;
        }

        github_add_inline_comment(params);
        console.log('✅ Inline comment on ' + filePath + ':' + inlineComment.line);
        return true;
    } catch (e) {
        console.warn('Inline comment failed (line not in diff?), falling back to PR comment on ' + filePath + ':' + inlineComment.line);
        try {
            postFallbackInlineComment(repoInfo, prNumber, filePath, inlineComment.line, commentText);
            return true;
        } catch (fallbackError) {
            console.warn('Failed to post fallback PR comment:', fallbackError);
            return false;
        }
    }
}

function triggerReworkIfConfigured(ticketKey, config, customParams) {
    if (!customParams || !customParams.autoStartRework || !customParams.autoStartReworkConfigFile) {
        return false;
    }

    try {
        return autoStart.triggerConfiguredWorkflowForTicket({
            ticketKey: ticketKey,
            customParams: customParams,
            config: config,
            configFile: customParams.autoStartReworkConfigFile,
            label: 'pr_test_automation_rework',
            stripKeys: [
                'removeLabel',
                'autoStartRework',
                'autoStartReworkConfigFile'
            ]
        });
    } catch (e) {
        console.warn('⚠️ autoStartRework trigger failed:', e.message || e);
        return false;
    }
}

function markForSmTestRework(ticketKey, tracker) {
    try {
        tracker.addLabel(ticketKey, 'sm_test_rework_triggered');
        console.log('✅ Added SM rework label: sm_test_rework_triggered');
        return true;
    } catch (e) {
        console.warn('⚠️ Failed to add SM rework label:', e.message || e);
        return false;
    }
}

function resolveCustomParams(params, config) {
    var merged = {};
    var patch = configLoader.resolveInstructions(
        'pr_test_automation_review',
        null,
        config
    ).jobParamPatch;
    if (patch && patch.customParams) {
        Object.assign(merged, patch.customParams);
    }
    Object.assign(
        merged,
        (params.jobParams && params.jobParams.customParams) ||
            params.customParams ||
            {}
    );
    return merged;
}

// Normalize recommendation: LLM may return "PASS"/"PASED" or "APPROVED" instead of "APPROVE",
// and "FAIL"/"FAILED" instead of "BLOCK".
function normalizeRecommendation(rec) {
    const value = String(rec || '').toUpperCase().trim();
    if (value === 'PASS' || value === 'PASSED' || value === 'APPROVED') return 'APPROVE';
    if (value === 'FAIL' || value === 'FAILED' || value === 'REJECT') return 'BLOCK';
    return rec;
}

// review JSON unreadable/missing: tell the tracker the SM trigger label was
// removed (so SM can retry), best-effort remove the trigger + WIP labels and
// fail the step.
function handleMissingReview(tracker, ticketKey, customParams, params) {
    tracker.postComment(ticketKey, 'h3. ⚠️ Review Error\n\nCould not read pr_review.json. Removed SM trigger label so SM can retry.');
    try {
        const smTriggerLabel = customParams.removeLabel || 'sm_test_review_triggered';
        tracker.removeLabel(ticketKey, smTriggerLabel);
        console.log('✅ Removed SM trigger label after missing review:', smTriggerLabel);
    } catch (e) {
        console.warn('Failed to remove SM trigger label after missing review:', e);
    }
    try {
        const wipLabelMissingReview = params.metadata && params.metadata.contextId
            ? params.metadata.contextId + '_wip'
            : 'pr_test_automation_review_wip';
        tracker.removeLabel(ticketKey, wipLabelMissingReview);
    } catch (e) {
        console.warn('Failed to remove WIP label after missing review:', e);
    }
    return { success: false, error: 'No review data found' };
}

// Step 4a: the general review comment (best-effort — a missing/unreadable
// comment file must not fail the step).
function postGeneralReviewComment(repoInfo, prNumber, reviewData) {
    if (!reviewData.generalComment) return;
    try {
        const commentText = readFile(reviewData.generalComment);
        if (commentText) {
            github_add_pr_comment({
                workspace: repoInfo.owner,
                repository: repoInfo.repo,
                pullRequestId: String(prNumber),
                text: commentText
            });
            console.log('✅ Posted general review comment to PR');
        }
    } catch (e) {
        console.warn('Failed to post general comment:', e);
    }
}

// Step 4b: queue for merge via pr_approved label (same pattern as stories/bugs).
// Returns the mergeSucceeded signal (true only when the PR was actually queued).
function queueApprovedPrForMerge(repoInfo, prNumber, tracker, ticketKey) {
    try {
        github_add_pr_label({
            workspace: repoInfo.owner,
            repository: repoInfo.repo,
            pullRequestId: String(prNumber),
            label: LABELS.PR_APPROVED
        });
        console.log('✅ Added pr_approved label to GitHub PR');
    } catch (e) {
        console.warn('Failed to add pr_approved to GitHub PR:', e);
    }
    try {
        tracker.addLabel(ticketKey, LABELS.PR_APPROVED);
        console.log('✅ Added pr_approved label to Jira ticket');
    } catch (e) {
        console.warn('Failed to add pr_approved to Jira ticket:', e);
    }
    console.log('✅ PR #' + prNumber + ' queued for merge via pr_approved');
    return true;
}

// Step 4: general comment, inline comments, resolved-thread cleanup and the
// pr_approved queueing. Returns the mergeSucceeded signal (true only when an
// approved PR was actually queued for merge).
function postReviewComments(repoInfo, prNumber, reviewData, tracker, ticketKey, isApproved) {
    if (prNumber && repoInfo) {
        postGeneralReviewComment(repoInfo, prNumber, reviewData);

        // Inline comments
        if (reviewData.inlineComments && reviewData.inlineComments.length > 0) {
            reviewData.inlineComments.forEach(function(ic) {
                postInlineComment(repoInfo, prNumber, ic);
            });
        }

        // Resolve threads that were fully fixed in this rework
        resolveApprovedThreads(repoInfo, prNumber, reviewData.resolvedThreadIds);

        if (isApproved) {
            return queueApprovedPrForMerge(repoInfo, prNumber, tracker, ticketKey);
        }
        return false;
    }
    console.warn('No PR info — skipping GitHub comments');
    return false;
}

// Step 6: on approval the ticket stays in In Review - Passed/Failed until SM
// merges the PR via the pr_approved flow; on changes-requested it moves to
// In Rework and triggers the rework continuation.
function moveTicketAfterReview(ticketKey, isApproved, tracker, jiraConfig, currentStatus, config, customParams) {
    if (isApproved) {
        // Ticket stays in In Review - Passed/Failed until SM merges the PR via pr_approved flow
        console.log('✅ Ticket stays in', currentStatus, '— SM will merge and move to final status');
        autoStart.triggerSmIfIdle({ config: config, customParams: customParams });
    } else {
        try {
            tracker.moveToStatus(ticketKey, jiraConfig.statuses.IN_REWORK);
            console.log('✅ Changes requested — moved', ticketKey, 'to In Rework');
            if (!triggerReworkIfConfigured(ticketKey, config, customParams)) {
                markForSmTestRework(ticketKey, tracker);
                autoStart.triggerSmIfIdle({ config: config, customParams: customParams });
            }
        } catch (e) {
            console.warn('Failed to move to In Rework:', e);
        }
    }
}

// Step 7: reviewed label + WIP/trigger label cleanup (every call is
// best-effort — a failing label op must not fail the step).
function finalizeReviewLabels(tracker, ticketKey, params) {
    try {
        tracker.addLabel(ticketKey, LABELS.AI_PR_REVIEWED);
    } catch (e) {}

    const wipLabel = params.metadata && params.metadata.contextId
        ? params.metadata.contextId + '_wip'
        : 'pr_test_automation_review_wip';
    try {
        tracker.removeLabel(ticketKey, wipLabel);
    } catch (e) {}

    try {
        tracker.removeLabel(ticketKey, 'sm_test_review_triggered');
        console.log('✅ Removed SM label: sm_test_review_triggered');
    } catch (e) {}
}

// Terminal status for the result payload (the ticket itself is moved by SM).
function decideFinalStatus(isApproved, mergeSucceeded, currentStatus, statuses) {
    if (isApproved && !mergeSucceeded) {
        return statuses.IN_REWORK;
    }
    if (isApproved) {
        return (currentStatus === statuses.IN_REVIEW_PASSED) ? statuses.PASSED : statuses.FAILED;
    }
    return statuses.IN_REWORK;
}

// Post token usage summary comments (e.g. [story_acceptance_criteria]: {...}) if any provider
// wrote outputs/*_usage.json during the agent run.
function postTokenUsageSummary(ticketKey, params) {
    try {
        tokenUsageComment.postTokenUsageComments(ticketKey, { initiator: params.initiator, customParams: tokenUsageComment.customParamsOf(params) });
    } catch (e) {
        console.warn('Failed to post token usage comments:', e);
    }
}

// Outer-catch cleanup: recreate the tracker when the failure happened before
// it was built, best-effort remove the SM trigger label, post the error
// comment and fail the step.
function failureCustomParamsOf(params) {
    return (params && params.customParams) ||
        (params && params.jobParams && params.jobParams.customParams) ||
        {};
}

function postFailureErrorComment(tracker, ticketKey, error) {
    try {
        tracker.removeLabel(ticketKey, 'sm_test_review_triggered');
    } catch (e) {}
    try {
        tracker.postComment(ticketKey, 'h3. ❌ Test Review Error\n\n{code}' + error.toString() + '{code}');
    } catch (e) {}
}

function loadFailureConfig(params) {
    try { return configLoader.loadProjectConfig(params); } catch (e) { return null; }
}

function resolveFailureTicketKey(params) {
    if (params.ticket) return params.ticket.key;
    return params.inputFolderPath ? params.inputFolderPath.split('/').pop() : null;
}

function handleActionFailure(params, error, tracker) {
    console.error('❌ Error in postTestReviewComments:', error);
    if (!tracker) tracker = trackersModule.createTracker(loadFailureConfig(params), failureCustomParamsOf(params));
    try {
        const ticketKey = resolveFailureTicketKey(params);
        if (ticketKey) {
            postFailureErrorComment(tracker, ticketKey, error);
        }
    } catch (e) {}
    return { success: false, error: error.toString() };
}

function action(params) {
    var tracker = null;
    try {
        const ticketKey = params.ticket.key;
        const jiraComment = params.response || '';
        const config = configLoader.loadProjectConfig(params.jobParams || params);
        const jiraConfig = config.jira;
        const customParams = resolveCustomParams(params, config);
        const workingDir = config.workingDir || null;
        tracker = trackersModule.createTracker(config, customParams);

        console.log('=== Processing test automation review for', ticketKey, '===');

        // Step 1: Read review data
        const reviewData = readReviewJson(ticketKey, workingDir);
        if (!reviewData) {
            return handleMissingReview(tracker, ticketKey, customParams, params);
        }

        reviewData.recommendation = normalizeRecommendation(reviewData.recommendation);
        const isApproved = reviewData.recommendation === 'APPROVE';
        console.log('Review recommendation:', reviewData.recommendation);

        // Step 2: Get current ticket status (to determine Passed vs Failed on approval)
        const currentStatus = getCurrentTicketStatus(ticketKey, tracker);
        console.log('Current ticket status:', currentStatus);

        // Step 3: Get repo info + PR number
        const repoInfo = gh.getGitHubRepoInfo();
        const { prNumber, prUrl } = getPRNumber(params, ticketKey, repoInfo);

        // Step 4: Post GitHub comments
        var mergeSucceeded = postReviewComments(repoInfo, prNumber, reviewData, tracker, ticketKey, isApproved);

        // Step 5: Post Jira comment
        try {
            if (jiraComment) {
                tracker.postComment(ticketKey, jiraComment);
                console.log('✅ Posted review comment to Jira');
            }
        } catch (e) {
            console.warn('Failed to post Jira comment:', e);
        }

        // Step 6: Move ticket status
        moveTicketAfterReview(ticketKey, isApproved, tracker, jiraConfig, currentStatus, config, customParams);

        // Step 7: Add label + remove WIP
        finalizeReviewLabels(tracker, ticketKey, params);

        var finalStatus = decideFinalStatus(isApproved, mergeSucceeded, currentStatus, jiraConfig.statuses);
        console.log('✅ Test review workflow complete:', isApproved ? (mergeSucceeded ? 'APPROVED' : 'MERGE CONFLICT') : 'CHANGES REQUESTED');

        postTokenUsageSummary(ticketKey, params);

        return {
            success: true,
            recommendation: reviewData.recommendation,
            ticketKey: ticketKey,
            mergeSucceeded: mergeSucceeded,
            finalStatus: finalStatus
        };

    } catch (error) {
        return handleActionFailure(params, error, tracker);
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action };
}

/**
 * Post Test Rework Results Action (postJSAction for pr_test_automation_rework)
 * After cursor agent fixes test issues and re-runs the test:
 * 1. Reads outputs/test_automation_result.json (new test result after fixes)
 * 2. Stages testing/ folder, commits, force-pushes to existing PR branch
 * 3. Replies to and resolves PR review threads (from outputs/review_replies.json)
 * 4. Posts PR comment with fix summary
 * 5. If test passed  → moves to In Review - Passed
 * 6. If test failed  → moves to In Review - Failed (bug may have changed)
 * 7. Posts Jira comment, removes WIP label
 *
 * gh-928: the action orchestration was split into pure planners/parsers
 * (normalizeTestStatus, buildResultErrorMessage, buildPRReworkComment,
 * buildAutoPRTitle, prNumberFromUrl, buildFallbackPR, prMatchesBranch) and
 * thin executors (runPublishGates, releaseReworkLock, postReworkBodyAndComment,
 * handleReplyItem, triggerAutoStart, resumeOrReport). Side effects, call order,
 * log lines and result shapes are unchanged — characterization-tested by
 * js/unit-tests/test_postTestReworkResults.js.
 */

var configLoader = require('./configLoader.js');
var autoStart = require('./common/autoStart.js');
var feedbackLoop = require('./common/feedbackLoop.js');
var prHelper = require('./common/pullRequest.js');
var mergeState = require('./common/mergeState.js');
const { GIT_CONFIG, LABELS } = require('./config.js');
var tokenUsageComment = require('./common/tokenUsageComment.js');
var trackersModule = require('./common/trackers.js');
var commentMarkup = require('./common/commentMarkup.js');

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var _trackerCtx = { config: null, customParams: {} };
var _trackerInst = null;
function initTracker(config, customParams) {
    _trackerCtx = { config: config || null, customParams: customParams || {} };
    _trackerInst = null;
}
function getTracker() {
    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
    return _trackerInst;
}


/**
 * Build the "Test Rework Completed" comment in the flavor of the ticket's
 * tracker (gh-770). The template historically hard-coded Jira wiki markup
 * (h3., *bold*, {code}) and was posted via raw jira_post_comment; on a
 * GitHub-backed tracker that renders as raw text garbage.
 *
 * @param {Object} flavor - a commentMarkup flavor bag (forTicket/forFlavor)
 * @param {Object} ctx    - { passed, testStatus, branchName, prUrl, fixSummary }
 * @returns {string} the rendered comment
 */
function buildTestReworkResultComment(flavor, ctx) {
    var m = flavor;
    var statusEmoji = ctx.passed ? '✅' : '❌';
    var comment = m.h(3, '🔧 Test Rework Completed') + '\n\n' +
        m.bold('Re-run result') + ': ' + statusEmoji + ' ' + m.bold(String(ctx.testStatus).toUpperCase()) + '\n' +
        m.bold('Branch') + ': ' + m.inline(ctx.branchName) + '\n';
    if (ctx.prUrl) {
        comment += m.bold('Pull Request') + ': ' + ctx.prUrl + '\n';
    }
    comment += '\n' + ctx.fixSummary;
    return comment;
}

// Canonical copy (gh-823/gh-912): the warning:/note: line filter lives in
// common/pullRequest.js once — this delegate keeps every local call site.
function cleanCommandOutput(output) {
    return prHelper.cleanCommandOutput(output);
}

function readFile(path) {
    try {
        const content = file_read({ path: path });
        return (content && content.trim()) ? content : null;
    } catch (e) {
        console.warn('Could not read file ' + path + ':', e);
        return null;
    }
}

function readResultJson() {
    try {
        const raw = readFile('outputs/test_automation_result.json');
        if (!raw) return null;
        return JSON.parse(raw);
    } catch (e) {
        console.error('Failed to parse test_automation_result.json:', e);
        return null;
    }
}

function findTestPRForTicket(scm, ticketKey) {
    try {
        const branchName = 'test/' + ticketKey;
        const openPRs = scm.listPrs('open') || [];
        const match = openPRs.filter(function(pr) {
            return pr.head && pr.head.ref && pr.head.ref === branchName;
        });
        if (match.length > 0) return match[0];
        console.warn('No open test PR found for branch', branchName);
        return null;
    } catch (e) {
        console.error('Failed to find PR:', e);
        return null;
    }
}

// ── gh-928 pure planners/parsers ─────────────────────────────────────────────

/**
 * Normalize a raw test-result status into the canonical passed/failed token.
 * Anything else is returned verbatim (the workflow treats it as not-passed).
 */
function normalizeTestStatus(rawStatus) {
    return (rawStatus === 'pass' || rawStatus === 'passed') ? 'passed' :
           (rawStatus === 'fail' || rawStatus === 'failed') ? 'failed' :
           rawStatus;
}

/**
 * The operator-facing message for an unreadable/invalid rework result JSON.
 * Distinguishes "file missing or empty" from "present but no status field".
 */
function buildResultErrorMessage(result) {
    return !result
        ? 'Could not read outputs/test_automation_result.json — file missing or empty.'
        : 'outputs/test_automation_result.json is missing required "status" field (got: ' + JSON.stringify(result) + '). The agent must write { "status": "passed" | "failed", ... }.';
}

/** The rework WIP label follows the workflow context when one is declared. */
function resolveWipLabel(actualParams) {
    return actualParams.metadata && actualParams.metadata.contextId
        ? actualParams.metadata.contextId + '_wip'
        : 'pr_test_automation_rework_wip';
}

/** Whether an open-PR list entry points at the given branch. */
function prMatchesBranch(pr, branchName) {
    return pr.head && pr.head.ref === branchName;
}

/** "KEY Summary" title for an auto-created rework PR, degrading to the key. */
function buildAutoPRTitle(ticket, ticketKey) {
    const summary = ticket && ticket.fields ? (ticket.fields.summary || ticketKey) : ticketKey;
    return ticketKey + ' ' + summary;
}

/** Best-effort PR number from a GitHub compare URL; null when not parseable. */
function prNumberFromUrl(prUrl) {
    if (!prUrl) return null;
    var m = prUrl.match(/\/pull\/(\d+)$/);
    return m ? parseInt(m[1], 10) : null;
}

/** Minimal PR shape built from a createPullRequest result (SCM-shape fallback). */
function buildFallbackPR(prResult, branchName) {
    return {
        number: prNumberFromUrl(prResult.prUrl),
        html_url: prResult.prUrl,
        head: { ref: branchName }
    };
}

/** The "🔧 Test Rework Complete" PR comment (GitHub Markdown). */
function buildPRReworkComment(ticketKey, testStatus, passed, prBodyContent) {
    const statusEmoji = passed ? '✅' : '❌';
    return '## 🔧 Test Rework Complete — ' + ticketKey + '\n\n' +
        '**Re-run result**: ' + statusEmoji + ' ' + testStatus.toUpperCase() + '\n\n' +
        '---\n\n' + prBodyContent;
}

// ── gh-1083: action() split — pure planners (called by the executors below) ──

/**
 * Which params shape carries the ticket (gh-1083): the ticket-shaped
 * dispatch params resolve to themselves, the jobParams-wrapped shape
 * unwraps to the jobParams body.
 */
function resolveActionContext(params) {
    var actualParams = params.ticket ? params : (params.jobParams || params);
    return { actualParams: actualParams, ticketKey: actualParams.ticket.key };
}

/** The operator-facing fix summary, degrading to the no-summary placeholder. */
function fixSummaryOf(actualParams) {
    return (actualParams && actualParams.response) || '_(No fix summary)_';
}

/** True when the rework result JSON is unreadable or carries no status. */
function isMissingResult(result) {
    return !result || !result.status;
}

/** Project config for the rework job (jobParams-wrapped or bare dispatch). */
function loadReworkProjectConfig(params) {
    return configLoader.loadProjectConfig(params.jobParams || params);
}

/** The SM idempotency label to remove after the run (null when not configured). */
function smRemoveLabelOf(customParams) {
    return (customParams && customParams.removeLabel) || null;
}

/**
 * Whether the test PR must merge the base branch before pushing (gh-1083).
 * Mirrors the original inline condition EXACTLY — strict `mergeable === false`
 * (an undefined mergeable is NOT dirty) — and a missing PR is never dirty.
 */
function decidePrIsDirty(pr) {
    if (!pr) return false;
    return pr.mergeable_state === 'dirty' || pr.mergeStateStatus === 'DIRTY' || pr.mergeable === false;
}

/** The In Review - Passed/Failed status pair for the rework outcome. */
function decideReworkTargetStatus(passed, statuses) {
    return passed
        ? { stageKey: 'IN_REVIEW_PASSED', targetStatus: statuses.IN_REVIEW_PASSED }
        : { stageKey: 'IN_REVIEW_FAILED', targetStatus: statuses.IN_REVIEW_FAILED };
}

// ── gh-1083: action() split — thin executors (side effects, unchanged order) ─

/** Missing/unreadable rework result: ⚠️ Rework Error comment + unlock. */
function reportMissingResult(ticketKey, result, config, customParams, releaseLock) {
    var errMsg = buildResultErrorMessage(result);
    console.error(errMsg);
    var tracker = trackersModule.createTracker(config, customParams);
    var mErr = commentMarkup.forTicket(ticketKey, customParams);
    try {
        tracker.postComment(
            ticketKey,
            mErr.h(3, '⚠️ Rework Error') + '\n\n' + errMsg + '\n\nCheck CI logs for the agent output.'
        );
    } catch (e) {}
    releaseLock();
    return { success: false, error: errMsg };
}

/** Configure the git author for the rework commit/push (failures ignored). */
function configureReworkGitAuthor(config) {
    try {
        cli_execute_command({ command: 'git config user.name "' + config.git.authorName + '"' });
        cli_execute_command({ command: 'git config user.email "' + config.git.authorEmail + '"' });
    } catch (e) {}
}

/** Step 2.5: the test PR for the ticket + its dirty state (with the dirty log line). */
function resolveReworkPr(scm, ticketKey, config) {
    var pr = findTestPRForTicket(scm, ticketKey);
    var prIsDirty = decidePrIsDirty(pr);
    if (pr && prIsDirty) {
        console.log('PR #' + pr.number + ' is dirty — will merge origin/' + ((config.git && config.git.baseBranch) || 'main'));
    }
    return { pr: pr, prIsDirty: prIsDirty };
}

/**
 * Step 2 git half: commitAndPush with the failure protocol — consult
 * resumeAgent once (a retry re-runs action(params)), otherwise ❌ Rework
 * Push Failed + unlock. Returns { branchName } on success or { terminal }
 * for the caller to return unchanged.
 */
function pushReworkBranch(params, ticketKey, passed, config, customParams, prIsDirty, releaseLock) {
    try {
        return { branchName: commitAndPush(ticketKey, passed, config, prIsDirty) };
    } catch (e) {
        console.error('Git operations failed:', e);
        if (resumeOrReport(ticketKey, customParams, config, 'test_rework_git_operations', '❌ Rework Push Failed', e)) {
            return { terminal: action(params) };
        }
        releaseLock();
        return { terminal: { success: false, error: e.toString() } };
    }
}

/** Step 3: thread replies, body refresh and the rework summary comment — when a PR exists. */
function publishReworkPrArtifacts(scm, pr, ticketKey, testStatus, passed, fixSummary) {
    if (!pr) {
        console.warn('No PR/MR found — skipping source-control comment');
        return;
    }
    postThreadReplies(scm, pr.number);

    // Post PR comment with fix summary + new test result (GitHub Markdown from pr_body.md)
    var prBodyContent = readFile('outputs/pr_body.md') || fixSummary;
    postReworkBodyAndComment(scm, pr, ticketKey, testStatus, passed, prBodyContent);
}

/** Step 4: move the ticket to In Review - Passed/Failed; returns the target status name. */
function moveReworkTicket(ticketKey, passed, jiraConfig) {
    var target = decideReworkTargetStatus(passed, jiraConfig.statuses);
    try {
        // gh-916: In Review - Passed/Failed can be tag-only (restricted ADO workflows) — stage-label fallback.
        var moveResult = getTracker().moveToStatusOrMark(ticketKey, target.targetStatus, target.stageKey);
        if (moveResult.moved || moveResult.marked) {
            console.log('✅ Moved', ticketKey, 'to', target.targetStatus);
        }
    } catch (e) {
        console.warn('Failed to move ticket status:', e);
    }
    return target.targetStatus;
}

/** Step 6: the flavored "Test Rework Completed" tracker comment (non-fatal on failure). */
function postReworkTrackerComment(ticketKey, config, customParams, pr, testStatus, branchName, passed, fixSummary) {
    try {
